params.spec:
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Which credential type each of the busiest identities presents (12 at most), with the number of Elasticsearch requests in each cell. Cells are coloured by credential type, in the same colours as the time chart beside it, and the count is printed in the cell, so a colour never stands for a number. Only Elasticsearch requests record a credential type, so identities seen only in Kibana or only anonymously are not on this chart. Rows keep about the height twelve would have, from the top, so a short window does not stretch a few identities into tall blocks.",
  "title": {
    "text": {
      "expr": "length(data('rows')) ? '' : 'No activity for this selection in this time range'"
    }
  },
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "view": {
      "stroke": null
    },
    "title": {
      "fontSize": 12,
      "fontWeight": 500,
      "anchor": "start"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 11
    }
  },
  "data": {
    "name": "rows",
    "url": {
      "%type%": "esql",
      "query": "SET unmapped_fields=\"nullify\"; FROM logs-elastic_cloud.serverless_audit.otel-* | WHERE @timestamp <= ?_tend AND @timestamp > ?_tstart | WHERE authentication.type IS NOT NULL | STATS events = COUNT(*) BY user.email, api_key.name, user.name, authentication.type | EVAL actor = COALESCE(user.email, api_key.name, user.name, \"<anonymous>\") | EVAL auth = CASE(authentication.type == \"api_key\", \"API key\", authentication.type == \"token\", \"Token\", authentication.type == \"realm\", \"Realm\", authentication.type == \"saml\", \"SAML\", authentication.type == \"anonymous\", \"Anonymous\", authentication.type == \"internal\", \"Internal\", authentication.type) | STATS events = SUM(events) BY actor, auth | SORT events DESC | LIMIT 2000 | EVAL actor = CASE((LENGTH(actor) == 20 AND actor RLIKE \"[-_A-Za-z0-9]{20}\" AND NOT actor RLIKE \"[0-9]{20}\"), CONCAT(LEFT(actor, 5), \"… · Cloud API key\"), actor)",
      "%timefield%": "@timestamp",
      "%context%": true
    }
  },
  "transform": [
    {
      "joinaggregate": [
        {
          "op": "sum",
          "field": "events",
          "as": "actor_total"
        }
      ],
      "groupby": [
        "actor"
      ]
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "rank"
        }
      ],
      "sort": [
        {
          "field": "actor_total",
          "order": "descending"
        },
        {
          "field": "actor",
          "order": "ascending"
        }
      ]
    },
    {
      "filter": "datum.rank <= 12"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 2
      },
      "encoding": {
        "color": {
          "field": "auth",
          "type": "nominal",
          "scale": {
            "domain": [
              "API key",
              "Token",
              "Realm",
              "SAML",
              "Anonymous",
              "Internal"
            ],
            "range": [
              "#54B399",
              "#6092C0",
              "#D36086",
              "#9170B8",
              "#D6BF57",
              "#DA8B45"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "color": "#1D1E24",
        "fontSize": 11,
        "fontWeight": 600,
        "baseline": "middle",
        "align": "center"
      },
      "encoding": {
        "text": {
          "field": "events",
          "type": "quantitative",
          "format": ","
        }
      }
    }
  ],
  "encoding": {
    "y": {
      "field": "actor",
      "type": "nominal",
      "sort": {
        "op": "min",
        "field": "rank",
        "order": "ascending"
      },
      "scale": {
        "paddingInner": 0.12,
        "paddingOuter": {
          "expr": "max(0.06, (12 - min(12, length(data('rows')))) / 2)"
        },
        "align": 0
      },
      "axis": {
        "title": "Identity · busiest, 12 at most",
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "labelLimit": 240,
        "ticks": false,
        "domain": false
      }
    },
    "x": {
      "field": "auth",
      "type": "nominal",
      "scale": {
        "paddingInner": 0.04
      },
      "axis": {
        "title": "Credential type",
        "titleOpacity": {
          "expr": "length(data('rows')) ? 1 : 0"
        },
        "labelAngle": 0,
        "orient": "top",
        "ticks": false,
        "domain": false
      }
    },
    "tooltip": [
      {
        "field": "actor",
        "title": "Identity"
      },
      {
        "field": "auth",
        "title": "Credential type"
      },
      {
        "field": "events",
        "title": "Events",
        "format": ","
      },
      {
        "field": "actor_total",
        "title": "All credentials",
        "format": ","
      }
    ]
  }
}
